21	import BoundingRect from 'zrender/src/core/BoundingRect';
22	import * as vec2 from 'zrender/src/core/vector';
23	import * as polygonContain from 'zrender/src/contain/polygon';
24	import { GeoJSON, GeoProjection, GeoSVGGraphicRoot } from './geoTypes';
