29	const TMP_TRANSFORM = [] as number[];
30	
31	function transformPoints(points: number[][], transform: matrix.MatrixArray) {
32	    for (let p = 0; p < points.length; p++) {
33	        vec2.applyTransform(points[p], points[p], transform);
34	    }
35	}
36	function updateBBoxFromPoints(
37	    points: ArrayLike<number>[],
38	    min: vec2.VectorArray,
39	    max: vec2.VectorArray,
40	    projection: GeoProjection
41	) {
42	    for (let i = 0; i < points.length; i++) {
43	        let p = points[i];
44	        if (projection) {
45	            // projection may return null point.
46	            p = projection.project(p as number[]);
47	        }
48	        if (p && isFinite(p[0]) && isFinite(p[1])) {
49	            vec2.min(min, min, p as vec2.VectorArray);
50	            vec2.max(max, max, p as vec2.VectorArray);
51	        }
52	    }
53	}
54	
55	function centroid(points: number[][]) {
56	    let signedArea = 0;
57	    let cx = 0;
58	    let cy = 0;
59	    const len = points.length;
60	    let x0 = points[len - 1][0];
61	    let y0 = points[len - 1][1];
62	    // Polygon should been closed.
63	    for (let i = 0; i < len; i++) {
64	        const x1 = points[i][0];
65	        const y1 = points[i][1];
66	        const a = x0 * y1 - x1 * y0;
67	        signedArea += a;
68	        cx += (x0 + x1) * a;
69	        cy += (y0 + y1) * a;
70	        x0 = x1;
71	        y0 = y1;
72	    }
73	
74	    return signedArea
75	        ? [cx / signedArea / 3, cy / signedArea / 3, signedArea]
76	        : [points[0][0] || 0, points[0][1] || 0];
77	}
78	export abstract class Region {
79	
80	    readonly name: string;
81	    readonly type: 'geoJSON' | 'geoSVG';
82	
83	    protected _center: number[];
84	    protected _rect: BoundingRect;
85	
86	    constructor(
87	        name: string
88	    ) {
89	        this.name = name;
90	    }
91	
92	    setCenter(center: number[]) {
93	        this._center = center;
94	    }
95	
96	    /**
97	     * Get center point in data unit. That is,
98	     * for GeoJSONRegion, the unit is lat/lng,
99	     * for GeoSVGRegion, the unit is SVG local coord.
100	     */
101	    getCenter() {
102	        let center = this._center;
103	        if (!center) {
104	            // In most cases there are no need to calculate this center.
105	            // So calculate only when called.
106	            center = this._center = this.calcCenter();
107	        }
108	        return center;
109	    }
110	
111	
112	    abstract calcCenter(): number[];
113	}
