115	export class GeoJSONPolygonGeometry {
116	    readonly type = 'polygon';
117	    exterior: number[][];
118	    interiors?: number[][][];
119	    constructor(exterior: number[][], interiors: number[][][]) {
120	        this.exterior = exterior;
121	        this.interiors = interiors;
122	    }
123	}
124	export class GeoJSONLineStringGeometry {
125	    readonly type = 'linestring';
126	    points: number[][][];
127	    constructor(points: number[][][]) {
128	        this.points = points;
129	    }
130	}
131	export class GeoJSONRegion extends Region {
132	
133	    readonly type = 'geoJSON';
134	
135	    readonly geometries: (GeoJSONPolygonGeometry | GeoJSONLineStringGeometry)[];
136	
137	    // Injected outside.
138	    properties: GeoJSON['features'][0]['properties'];
139	
140	    constructor(
141	        name: string,
142	        geometries: GeoJSONRegion['geometries'],
143	        cp: GeoJSON['features'][0]['properties']['cp']
144	    ) {
145	        super(name);
146	
147	        this.geometries = geometries;
148	
149	        this._center = cp && [cp[0], cp[1]];
150	    }
151	
152	    calcCenter() {
153	        const geometries = this.geometries;
154	        let largestGeo: GeoJSONPolygonGeometry;
155	        let largestGeoSize = 0;
156	        for (let i = 0; i < geometries.length; i++) {
157	            const geo = geometries[i] as GeoJSONPolygonGeometry;
158	            const exterior = geo.exterior;
159	            // Simple trick to use points count instead of polygon area as region size.
160	            // Ignore linestring
161	            const size = exterior && exterior.length;
162	            if (size > largestGeoSize) {
163	                largestGeo = geo;
164	                largestGeoSize = size;
165	            }
166	        }
167	        if (largestGeo) {
168	            return centroid(largestGeo.exterior);
169	        }
170	
171	        // from bounding rect by default.
172	        const rect = this.getBoundingRect();
173	        return [
174	            rect.x + rect.width / 2,
175	            rect.y + rect.height / 2
176	        ];
177	    }
178	
179	    getBoundingRect(projection?: GeoProjection): BoundingRect {
180	        let rect = this._rect;
181	        // Always recalculate if using projection.
182	        if (rect && !projection) {
183	            return rect;
184	        }
185	
186	        const min = [Infinity, Infinity];
187	        const max = [-Infinity, -Infinity];
188	        const geometries = this.geometries;
189	
190	        each(geometries, geo => {
191	            if (geo.type === 'polygon') {
192	                // Doesn't consider hole
193	                updateBBoxFromPoints(geo.exterior, min, max, projection);
194	            }
195	            else {
196	                each(geo.points, (points) => {
197	                    updateBBoxFromPoints(points, min, max, projection);
198	                });
199	            }
200	        });
201	        // Normalie invalid bounding.
202	        if (!(isFinite(min[0]) && isFinite(min[1]) && isFinite(max[0]) && isFinite(max[1]))) {
203	            min[0] = min[1] = max[0] = max[1] = 0;
204	        }
205	        rect = new BoundingRect(
206	            min[0], min[1], max[0] - min[0], max[1] - min[1]
207	        );
208	        if (!projection) {
209	            this._rect = rect;
210	        }
211	
212	        return rect;
213	    }
214	
215	    contain(coord: number[]): boolean {
216	        const rect = this.getBoundingRect();
217	        const geometries = this.geometries;
218	        if (!rect.contain(coord[0], coord[1])) {
219	            return false;
220	        }
221	        loopGeo: for (let i = 0, len = geometries.length; i < len; i++) {
222	            const geo = geometries[i];
223	            // Only support polygon.
224	            if (geo.type !== 'polygon') {
225	                continue;
226	            }
227	            const exterior = geo.exterior;
228	            const interiors = geo.interiors;
229	            if (polygonContain.contain(exterior, coord[0], coord[1])) {
230	                // Not in the region if point is in the hole.
231	                for (let k = 0; k < (interiors ? interiors.length : 0); k++) {
232	                    if (polygonContain.contain(interiors[k], coord[0], coord[1])) {
233	                        continue loopGeo;
234	                    }
235	                }
236	                return true;
237	            }
238	        }
239	        return false;
240	    }
241	
242	    /**
243	     * Transform the raw coords to target bounding.
244	     * @param x
245	     * @param y
246	     * @param width
247	     * @param height
248	     */
249	    transformTo(x: number, y: number, width: number, height: number): void {
250	        let rect = this.getBoundingRect();
251	        const aspect = rect.width / rect.height;
252	        if (!width) {
253	            width = aspect * height;
254	        }
255	        else if (!height) {
256	            height = width / aspect;
257	        }
258	        const target = new BoundingRect(x, y, width, height);
259	        const transform = rect.calculateTransform(target);
260	        const geometries = this.geometries;
261	        for (let i = 0; i < geometries.length; i++) {
262	            const geo = geometries[i];
263	            if (geo.type === 'polygon') {
264	                transformPoints(geo.exterior, transform);
265	                each(geo.interiors, interior => {
266	                    transformPoints(interior, transform);
267	                });
268	            }
269	            else {
270	                each(geo.points, points => {
271	                    transformPoints(points, transform);
272	                });
273	            }
274	        }
275	        rect = this._rect;
276	        rect.copy(target);
277	        // Update center
278	        this._center = [
279	            rect.x + rect.width / 2,
280	            rect.y + rect.height / 2
281	        ];
282	    }
283	
284	    cloneShallow(name: string): GeoJSONRegion {
285	        name == null && (name = this.name);
286	        const newRegion = new GeoJSONRegion(name, this.geometries, this._center);
287	        newRegion._rect = this._rect;
288	        newRegion.transformTo = null; // Simply avoid to be called.
289	        return newRegion;
290	    }
291	}
292	
293	export class GeoSVGRegion extends Region {
294	
295	    readonly type = 'geoSVG';
296	
297	    // Can only be used to calculate, but not be modified.
298	    // Because this el may not belong to this view,
299	    // but been displaying on some other view.
300	    private _elOnlyForCalculate: Element;
301	
302	    constructor(
303	        name: string,
304	        elOnlyForCalculate: Element
305	    ) {
306	        super(name);
307	        this._elOnlyForCalculate = elOnlyForCalculate;
308	    }
309	
310	    calcCenter(): number[] {
311	        const el = this._elOnlyForCalculate;
312	        const rect = el.getBoundingRect();
313	        const center = [
314	            rect.x + rect.width / 2,
315	            rect.y + rect.height / 2
316	        ];
317	
318	        const mat = matrix.identity(TMP_TRANSFORM);
319	
320	        let target = el;
321	        while (target && !(target as GeoSVGGraphicRoot).isGeoSVGGraphicRoot) {
322	            matrix.mul(mat, target.getLocalTransform(), mat);
323	            target = target.parent;
324	        }
325	
326	        matrix.invert(mat, mat);
327	
328	        vec2.applyTransform(center, center, mat);
329	
330	        return center;
331	    }
332	
333	}
