+import SeriesData from '../src/data/SeriesData';
+import Model from '../src/model/Model';
+
+function getDimValues(data: SeriesData, dim: string): number[] {
+    const values: number[] = [];
+    for (let i = 0; i < data.count(); i++) {
+        values.push(data.get(dim, i) as number);
+    }
+    return values;
+}
+
+describe('minmax-sampling-behavior', function () {
+    it('minmaxDownSample keeps both min and max of each frame in original order', function () {
+        const data = new SeriesData(['x', 'y'], new Model());
+        data.initData([[0, 1], [1, 5], [2, -3], [3, 2], [4, 4], [5, -1]]);
+
+        // rate 0.5 -> frameSize 2
+        const sampled = data.minmaxDownSample('y', 0.5);
+
+        expect(sampled.count()).toBe(6);
+        // frame [1, 5]:   min=1 (idx 0), max=5 (idx 1)  -> 1, 5
+        // frame [-3, 2]:  min=-3 (idx 2), max=2 (idx 3) -> -3, 2
+        // frame [4, -1]:  max=4 (idx 4) comes before min=-1 (idx 5) -> 4, -1
+        expect(getDimValues(sampled, 'y')).toEqual([1, 5, -3, 2, 4, -1]);
+        // x values stay attached to the picked raw points
+        expect(getDimValues(sampled, 'x')).toEqual([0, 1, 2, 3, 4, 5]);
+    });
+
+    it('minmaxDownSample handles a final smaller frame', function () {
+        const data = new SeriesData(['x', 'y'], new Model());
+        data.initData([[0, 1], [1, 9], [2, 3], [3, 8], [4, 7]]);
+
+        const sampled = data.minmaxDownSample('y', 0.5);
+
+        // frames [1, 9] -> 1, 9 ; [3, 8] -> 3, 8 ; final frame [7] -> 7, 7
+        expect(sampled.count()).toBe(6);
+        expect(getDimValues(sampled, 'y')).toEqual([1, 9, 3, 8, 7, 7]);
+    });
+
+    it('minmaxDownSample preserves extrema that the old value sampler dropped', function () {
+        const data = new SeriesData(['x', 'y'], new Model());
+        // Both a high peak and a low trough inside the same frame.
+        data.initData([[0, 0], [1, 100], [2, -80], [3, 0]]);
+
+        const sampled = data.minmaxDownSample('y', 0.25); // frameSize 4
+
+        expect(sampled.count()).toBe(2);
+        // max 100 occurs before min -80 in the frame, so order is 100, -80
+        expect(getDimValues(sampled, 'y')).toEqual([100, -80]);
+    });
+});
